import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] parent = new int[n];
        long[] values = new long[n];
        for (int i = 0; i < n; i++) parent[i] = nextInt();
        for (int i = 0; i < n; i++) values[i] = nextLong();
        // Compressed child lists: children of u are child[start[u] .. start[u + 1]).
        int[] start = new int[n + 1];
        for (int i = 1; i < n; i++) start[parent[i] + 1]++;
        for (int i = 0; i < n; i++) start[i + 1] += start[i];
        int[] fill = Arrays.copyOf(start, n), child = new int[Math.max(n - 1, 0)];
        for (int i = 1; i < n; i++) child[fill[parent[i]]++] = i;
        // BFS order lists every parent before its children; no recursion on deep chains.
        int[] order = new int[n];
        int size = 1;
        for (int k = 0; k < size; k++)
            for (int j = start[order[k]]; j < start[order[k] + 1]; j++) order[size++] = child[j];
        long[] best = new long[n];
        long answer = Long.MIN_VALUE;
        for (int k = n - 1; k >= 0; k--) {
            int u = order[k];
            long extend = 0;
            for (int j = start[u]; j < start[u + 1]; j++) extend = Math.max(extend, best[child[j]]);
            best[u] = values[u] + extend;
            answer = Math.max(answer, best[u]);
        }
        System.out.println(answer);
    }
}

